        int64_t blockLen = (blockIdx < formerNum) ? formerLength : tailLength;
        int64_t offset = 0;
        if (blockIdx < formerNum) {
            offset = blockIdx * formerLength;
        } else {
            offset = formerNum * formerLength + (blockIdx - formerNum) * tailLength;
        }

        this->blockOffset = offset;
        this->blockLength = blockLen;

        inputGm.SetGlobalBuffer((__gm__ T *)input, inputNumel);
        outputGm.SetGlobalBuffer((__gm__ T *)output, outputNumel);

        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));
