            int64_t outIdx = outStart + processed;
            int64_t inIdx = MapOutputToInput(outIdx);

            // Try to find how many contiguous elements we can copy
            int64_t maxContig = actualLen - processed;
            if (maxContig > chunkSize) {
                maxContig = chunkSize;
