#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int64_t MAX_DIM = 8;

struct RepeatTilingData {
    int64_t totalLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t inputNumel;
    int64_t outputNumel;
    int64_t ndim;
    int64_t inputShape[MAX_DIM];
    int64_t outputShape[MAX_DIM];
};

template <typename T>
class KernelRepeat {
public:
    __aicore__ inline KernelRepeat() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR tiling)
    {
        auto *tilingData = reinterpret_cast<__gm__ RepeatTilingData *>(tiling);
        this->totalLength = tilingData->totalLength;
        this->formerNum = tilingData->formerNum;
        this->formerLength = tilingData->formerLength;
        this->tailNum = tilingData->tailNum;
        this->tailLength = tilingData->tailLength;
        this->tileLength = tilingData->tileLength;
        this->inputNumel = tilingData->inputNumel;
        this->outputNumel = tilingData->outputNumel;
        this->ndim = tilingData->ndim;

        for (int64_t i = 0; i < ndim && i < MAX_DIM; ++i) {
            this->inputShape[i] = tilingData->inputShape[i];
            this->outputShape[i] = tilingData->outputShape[i];
        }

        int64_t blockIdx = AscendC::GetBlockIdx();
        int64_t blockLen = (blockIdx < formerNum) ? formerLength : tailLength;
        int64_t offset = 0;
        if (blockIdx < formerNum) {
            offset = blockIdx * formerLength;
        } else {
            offset = formerNum * formerLength + (blockIdx - formerNum) * tailLength;
        }

        this->blockOffset = offset;
        this->blockLength = blockLen;

        inputGm.SetGlobalBuffer((__gm__ T *)input, inputNumel);
        outputGm.SetGlobalBuffer((__gm__ T *)output, outputNumel);

        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        if (blockLength <= 0) {
            return;
        }

        int64_t tileNum = (blockLength + tileLength - 1) / tileLength;
        int64_t tailTileLength = blockLength - (tileNum - 1) * tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            ComputeTile(i, tileLength);
        }
        if (tileNum > 0) {
            ComputeTile(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void ComputeTile(int64_t progress, int64_t curTileLength)
    {
        int64_t outStart = blockOffset + progress * tileLength;
        int64_t actualLen = (outStart + curTileLength > blockOffset + blockLength)
                            ? (blockOffset + blockLength - outStart)
                            : curTileLength;
        if (actualLen <= 0) {
            return;
        }

        int64_t processed = 0;
        while (processed < actualLen) {
            int64_t outIdx = outStart + processed;
            int64_t inIdx = MapOutputToInput(outIdx);

            // Copy single element
            AscendC::LocalTensor<T> tmpLocal = inQueue.AllocTensor<T>();
            AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
            AscendC::DataCopyPad(tmpLocal, inputGm[inIdx], copyParams);
            inQueue.EnQue(tmpLocal);

            tmpLocal = inQueue.DeQue<T>();
            AscendC::DataCopyPad(outputGm[outIdx], tmpLocal, copyParams);
            inQueue.FreeTensor(tmpLocal);

            processed += 1;
        }
    }

    __aicore__ inline int64_t MapOutputToInput(int64_t outIdx)
    {
        int64_t coords[MAX_DIM];
        int64_t temp = outIdx;
        for (int64_t d = ndim - 1; d >= 0; --d) {
            coords[d] = temp % outputShape[d];
            temp = temp / outputShape[d];
        }

        int64_t inIdx = 0;
        for (int64_t d = 0; d < ndim; ++d) {
            int64_t inCoord = coords[d] % inputShape[d];
            inIdx = inIdx * inputShape[d] + inCoord;
        }
        return inIdx;
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::GlobalTensor<T> inputGm;
    AscendC::GlobalTensor<T> outputGm;

    int64_t totalLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t inputNumel;
    int64_t outputNumel;
    int64_t ndim;
    int64_t inputShape[MAX_DIM];
    int64_t outputShape[MAX_DIM];
    int64_t blockOffset;
    int64_t blockLength;
};

extern "C" __global__ __aicore__ void repeat_half(GM_ADDR input, GM_ADDR output, GM_ADDR tiling)
{
    KernelRepeat<half> op;
    op.Init(input, output, tiling);
    op.Process();
}

extern "C" __global__ __aicore__ void repeat_float(GM_ADDR input, GM_ADDR output, GM_ADDR tiling)
{
    KernelRepeat<float> op;
    op.Init(input, output, tiling);
    op.Process();
}
