#include <ATen/ATen.h>
#include <torch/library.h>
#include <acl/acl_rt.h>
#include <cstring>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t MAX_DIM = 8;

struct RepeatTilingData {
    int64_t totalLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t inputNumel;
    int64_t outputNumel;
    int64_t ndim;
    int64_t inputShape[MAX_DIM];
    int64_t outputShape[MAX_DIM];
};

// Forward declarations for kernel functions (defined in op_kernel/repeat.cpp)
extern "C" {
void repeat_half(void*, void*, void*);
void repeat_float(void*, void*, void*);
}

at::Tensor repeat(const at::Tensor &self, at::IntArrayRef repeats)
{
    // ---- 输入校验 ----
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kBFloat16 || self.scalar_type() == at::kFloat,
                "repeat: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
    TORCH_CHECK(self.is_contiguous(), "repeat: input tensor must be contiguous");
    TORCH_CHECK(static_cast<int64_t>(repeats.size()) == self.dim(),
                "repeat: repeats dimensions (", repeats.size(), ") must match input dimensions (", self.dim(), ")");

    // ---- 计算输出 shape ----
    std::vector<int64_t> outputShape;
    for (int64_t i = 0; i < self.dim(); ++i) {
        outputShape.push_back(self.size(i) * repeats[i]);
    }

    at::Tensor output = at::empty(outputShape, self.options());

    int64_t inputNumel = self.numel();
    int64_t outputNumel = output.numel();
    if (outputNumel == 0) {
        return output;
    }

    int64_t dtypeSize = self.element_size();

    // ---- 获取硬件参数 ----
    int64_t coreNum = 40;  // Ascend910B2 has 40 cores

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    int64_t totalLength = outputNumel;
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore * dtypeSize + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH / dtypeSize;
    if (totalLengthCoreAlign < 1) totalLengthCoreAlign = 1;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;
    if (tailLength < 0) {
        tailLength = totalLengthCoreAlign;
        formerNum = usedCoreNum;
    }

    // ---- UB 级 tiling (核内切分) ----
    int64_t ubSizeLimit = 192 * 1024;  // 192KB UB size for 910B
    int64_t bufferCoefficient = 4;
    int64_t maxTileElements = ubSizeLimit / (bufferCoefficient * dtypeSize);
    if (maxTileElements < 1) maxTileElements = 1;
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements < 1) alignElements = 1;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < 1) tileLength = 1;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- 准备 tiling data ----
    RepeatTilingData tilingData;
    tilingData.totalLength = totalLength;
    tilingData.formerNum = formerNum;
    tilingData.formerLength = formerLength;
    tilingData.tailNum = usedCoreNum - formerNum;
    tilingData.tailLength = tailLength;
    tilingData.tileLength = tileLength;
    tilingData.inputNumel = inputNumel;
    tilingData.outputNumel = outputNumel;
    tilingData.ndim = self.dim();

    for (int64_t i = 0; i < self.dim() && i < MAX_DIM; ++i) {
        tilingData.inputShape[i] = self.size(i);
        tilingData.outputShape[i] = outputShape[i];
    }
    for (int64_t i = self.dim(); i < MAX_DIM; ++i) {
        tilingData.inputShape[i] = 1;
        tilingData.outputShape[i] = 1;
    }

    // Allocate workspace for tiling data on device
    void *workspacePtr = nullptr;
    aclrtMalloc(&workspacePtr, sizeof(RepeatTilingData), ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMemcpy(workspacePtr, sizeof(RepeatTilingData), &tilingData, sizeof(RepeatTilingData), ACL_MEMCPY_HOST_TO_DEVICE);

    // ---- Launch kernel using aclrtLaunchKernel ----
    void *inputPtr = const_cast<void*>(self.data_ptr());
    void *outputPtr = const_cast<void*>(output.data_ptr());

    void *args[] = {&inputPtr, &outputPtr, &workspacePtr};

    if (self.scalar_type() == at::kHalf || self.scalar_type() == at::kBFloat16) {
        aclrtLaunchKernel("repeat_half", blockDim, args, sizeof(args), nullptr, nullptr);
    } else {
        aclrtLaunchKernel("repeat_float", blockDim, args, sizeof(args), nullptr, nullptr);
    }

    aclrtSynchronizeStream(nullptr);
    aclrtFree(workspacePtr);

    return output;
}

}  // namespace ascend_kernel
